'use client'

import { useState, type ComponentProps } from 'react'
import {
  endOfMonth,
  endOfWeek,
  format,
  isSameDay,
  startOfDay,
  startOfMonth,
  startOfWeek,
  subDays,
  subMonths,
} from 'date-fns'
import { CalendarRegular } from '@mingcute/react/core-regular'
import type { DateRange, Matcher } from 'react-day-picker'

import { cn } from '@/lib/utils'
import { Button } from '@ui/button'
import { Calendar } from '@ui/calendar'
import { Input } from '@ui/input'
import { Popover, PopoverContent, PopoverTrigger } from '@ui/popover'

type CaptionLayout = NonNullable<ComponentProps<typeof Calendar>['captionLayout']>

const YEAR_START = new Date(1900, 0)

function yearEnd() {
  return new Date(new Date().getFullYear() + 10, 11)
}

const pickerTriggerClassName =
  'w-full min-w-0 justify-start overflow-visible whitespace-normal text-left font-normal data-[empty=true]:text-oc-muted-foreground'

function DatePickerActions({
  onClear,
  onDone,
}: {
  onClear: () => void
  onDone: () => void
}) {
  return (
    <div className="flex justify-end gap-2 border-t border-solid border-oc-border px-3 py-2.5">
      <Button type="button" variant="outline" size="sm" onClick={onClear}>
        Clear
      </Button>
      <Button type="button" size="sm" onClick={onDone}>
        Done
      </Button>
    </div>
  )
}

type DatePickerProps = {
  className?: string
  selected?: Date
  defaultSelected?: Date
  onSelect?: (date: Date | undefined) => void
  disabled?: Matcher | Matcher[]
  placeholder?: string
  captionLayout?: CaptionLayout
  startMonth?: Date
  endMonth?: Date
}

function DatePicker({
  className,
  selected,
  defaultSelected,
  onSelect,
  disabled,
  placeholder = 'Pick a date',
  captionLayout = 'dropdown',
  startMonth = YEAR_START,
  endMonth,
}: DatePickerProps) {
  const [open, setOpen] = useState(false)
  const [uncontrolled, setUncontrolled] = useState<Date | undefined>(defaultSelected)
  const date = selected ?? uncontrolled

  function commit(next: Date | undefined) {
    setUncontrolled(next)
    onSelect?.(next)
  }

  return (
    <div className="w-full min-w-0">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          className="w-full"
          render={
            <Button
              variant="outline"
              data-empty={!date}
              className={cn(pickerTriggerClassName, className)}
            />
          }
        >
          <CalendarRegular data-icon="inline-start" />
          {date ? (
            <span className="min-w-0 flex-1 truncate">{format(date, 'PPP')}</span>
          ) : (
            <span className="min-w-0 flex-1">{placeholder}</span>
          )}
        </PopoverTrigger>
        <PopoverContent className="w-auto overflow-hidden p-0" align="start">
          <Calendar
            className="p-5"
            mode="single"
            captionLayout={captionLayout}
            startMonth={startMonth}
            endMonth={endMonth ?? yearEnd()}
            selected={date}
            onSelect={commit}
            disabled={disabled}
          />
          <DatePickerActions onClear={() => commit(undefined)} onDone={() => setOpen(false)} />
        </PopoverContent>
      </Popover>
    </div>
  )
}

type DateTimePickerProps = {
  className?: string
  selected?: Date
  defaultSelected?: Date
  onSelect?: (date: Date | undefined) => void
  disabled?: Matcher | Matcher[]
  placeholder?: string
  captionLayout?: CaptionLayout
  startMonth?: Date
  endMonth?: Date
}

function timeValue(date: Date | undefined) {
  if (!date) return '00:00'
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`
}

function withTime(date: Date, time: string) {
  const [hours, minutes] = time.split(':').map(Number)
  const next = new Date(date)
  next.setHours(hours || 0, minutes || 0, 0, 0)
  return next
}

function DateTimePicker({
  className,
  selected,
  defaultSelected,
  onSelect,
  disabled,
  placeholder = 'Pick date and time',
  captionLayout = 'dropdown',
  startMonth = YEAR_START,
  endMonth,
}: DateTimePickerProps) {
  const [open, setOpen] = useState(false)
  const [uncontrolled, setUncontrolled] = useState<Date | undefined>(defaultSelected)
  const date = selected ?? uncontrolled

  function commit(next: Date | undefined) {
    setUncontrolled(next)
    onSelect?.(next)
  }

  return (
    <div className="w-full min-w-0">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          className="w-full"
          render={
            <Button
              variant="outline"
              data-empty={!date}
              className={cn(pickerTriggerClassName, className)}
            />
          }
        >
          <CalendarRegular data-icon="inline-start" />
          {date ? (
            <span className="min-w-0 flex-1 truncate">{format(date, 'PPp')}</span>
          ) : (
            <span className="min-w-0 flex-1">{placeholder}</span>
          )}
        </PopoverTrigger>
        <PopoverContent className="w-auto overflow-hidden p-0" align="start">
          <Calendar
            className="p-5"
            mode="single"
            captionLayout={captionLayout}
            startMonth={startMonth}
            endMonth={endMonth ?? yearEnd()}
            selected={date}
            onSelect={(next) => {
              if (!next) {
                commit(undefined)
                return
              }
              commit(date ? withTime(next, timeValue(date)) : withTime(next, '09:00'))
            }}
            disabled={disabled}
          />
          <div className="border-t border-solid border-oc-border p-3">
            <Input
              type="time"
              aria-label="Time"
              value={timeValue(date)}
              disabled={!date}
              onChange={(event) => {
                if (!date) return
                commit(withTime(date, event.target.value))
              }}
            />
          </div>
          <DatePickerActions onClear={() => commit(undefined)} onDone={() => setOpen(false)} />
        </PopoverContent>
      </Popover>
    </div>
  )
}

const WEEK_STARTS_ON = 1 as const

const RANGE_PRESETS = [
  {
    label: 'Today',
    range: () => {
      const today = startOfDay(new Date())
      return { from: today, to: today }
    },
  },
  {
    label: 'Yesterday',
    range: () => {
      const yesterday = startOfDay(subDays(new Date(), 1))
      return { from: yesterday, to: yesterday }
    },
  },
  {
    label: 'This week',
    range: () => ({
      from: startOfWeek(new Date(), { weekStartsOn: WEEK_STARTS_ON }),
      to: endOfWeek(new Date(), { weekStartsOn: WEEK_STARTS_ON }),
    }),
  },
  {
    label: 'This month',
    range: () => ({
      from: startOfMonth(new Date()),
      to: endOfMonth(new Date()),
    }),
  },
  {
    label: 'Last month',
    range: () => {
      const last = subMonths(new Date(), 1)
      return { from: startOfMonth(last), to: endOfMonth(last) }
    },
  },
] as const

function isSameRange(left?: DateRange, right?: DateRange) {
  if (!left?.from || !left.to || !right?.from || !right.to) return false
  return isSameDay(left.from, right.from) && isSameDay(left.to, right.to)
}

type DatePickerRangeProps = {
  className?: string
  selected?: DateRange
  defaultSelected?: DateRange
  onSelect?: (range: DateRange | undefined) => void
  disabled?: Matcher | Matcher[]
  placeholder?: string
  captionLayout?: CaptionLayout
  startMonth?: Date
  endMonth?: Date
}

function DatePickerRange({
  className,
  selected,
  defaultSelected,
  onSelect,
  disabled,
  placeholder = 'Pick a date',
  captionLayout = 'dropdown',
  startMonth = YEAR_START,
  endMonth,
}: DatePickerRangeProps) {
  const [open, setOpen] = useState(false)
  const [uncontrolled, setUncontrolled] = useState<DateRange | undefined>(defaultSelected)
  const range = selected ?? uncontrolled
  const [visibleMonth, setVisibleMonth] = useState<Date>(range?.from ?? new Date())

  function commit(next: DateRange | undefined) {
    setUncontrolled(next)
    onSelect?.(next)
    if (next?.from) setVisibleMonth(next.from)
  }

  return (
    <div className="w-full min-w-0">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          className="w-full"
          render={
            <Button
              variant="outline"
              data-empty={!range?.from}
              className={cn(pickerTriggerClassName, className)}
            />
          }
        >
          <CalendarRegular data-icon="inline-start" />
          <span className={cn('min-w-0 flex-1', range?.from ? 'truncate' : undefined)}>
            {range?.from
              ? range.to
                ? `${format(range.from, 'LLL dd, y')} - ${format(range.to, 'LLL dd, y')}`
                : format(range.from, 'LLL dd, y')
              : placeholder}
          </span>
        </PopoverTrigger>
      <PopoverContent className="w-auto overflow-hidden p-0" align="start">
        <div className="flex">
          <div className="flex w-36 shrink-0 flex-col gap-0.5 border-r border-solid border-oc-border p-2">
            {RANGE_PRESETS.map((preset) => {
              const next = preset.range()
              const active = isSameRange(range, next)
              return (
                <button
                  key={preset.label}
                  type="button"
                  className={cn(
                    'cursor-pointer rounded-md px-2.5 py-1.5 text-left text-sm font-medium text-oc-foreground',
                    active ? 'bg-oc-primary/10' : 'hover:bg-oc-muted',
                  )}
                  onClick={() => commit(next)}
                >
                  {preset.label}
                </button>
              )
            })}
          </div>
          <div>
            <Calendar
              className="p-5"
              mode="range"
              numberOfMonths={2}
              showOutsideDays
              captionLayout={captionLayout}
              startMonth={startMonth}
              endMonth={endMonth ?? yearEnd()}
              month={visibleMonth}
              onMonthChange={setVisibleMonth}
              selected={range}
              onSelect={commit}
              disabled={disabled}
            />
            <DatePickerActions onClear={() => commit(undefined)} onDone={() => setOpen(false)} />
          </div>
        </div>
      </PopoverContent>
      </Popover>
    </div>
  )
}

export { DatePicker, DatePickerRange, DateTimePicker }
export type { DatePickerProps, DatePickerRangeProps, DateTimePickerProps }

'use client'

import * as React from 'react'
import {
  DayPicker,
  getDefaultClassNames,
  useDayPicker,
  type DayButton,
  type Locale,
  type MonthCaptionProps,
} from 'react-day-picker'
import {
  DownRegular,
  LeftRegular,
  RightRegular,
} from '@mingcute/react/core-regular'

import { cn } from '@/lib/utils'
import { Button, buttonVariants } from '@ui/button'

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = 'label',
  buttonVariant = 'ghost',
  locale,
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>['variant']
}) {
  const defaultClassNames = getDefaultClassNames()
  const isMultipleMonths = (props.numberOfMonths ?? 1) > 1

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        'group/calendar bg-oc-background p-0 [--cell-size:2rem]',
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className,
      )}
      captionLayout={captionLayout === 'dropdown' ? 'label' : captionLayout}
      locale={locale}
      formatters={{
        formatMonthDropdown: (date) =>
          date.toLocaleString(locale?.code, { month: 'short' }),
        formatWeekdayName: (date) =>
          date.toLocaleDateString(locale?.code ?? 'en-US', { weekday: 'short' }).slice(0, 2),
        ...formatters,
      }}
      classNames={{
        root: cn('w-fit', defaultClassNames.root),
        months: cn(
          'relative flex flex-col gap-6',
          isMultipleMonths && 'sm:flex-row',
          defaultClassNames.months,
        ),
        month: cn('flex w-full flex-col gap-6', defaultClassNames.month),
        nav: cn(
          'absolute inset-x-0 top-0 flex items-center gap-2',
          isMultipleMonths ? 'justify-between' : 'justify-end',
          defaultClassNames.nav,
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant, size: 'icon-xs' }),
          'size-5 min-w-5 p-0 text-oc-foreground select-none aria-disabled:opacity-35',
          defaultClassNames.button_previous,
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant, size: 'icon-xs' }),
          'size-5 min-w-5 p-0 text-oc-foreground select-none aria-disabled:opacity-35',
          defaultClassNames.button_next,
        ),
        month_caption: cn(
          'relative flex h-8 w-full items-center',
          isMultipleMonths ? 'justify-center px-8' : 'justify-start',
          defaultClassNames.month_caption,
        ),
        dropdowns: cn(
          'flex h-8 w-full items-center justify-start gap-2 text-sm font-medium',
          defaultClassNames.dropdowns,
        ),
        dropdown_root: cn(
          'relative rounded-md border border-solid border-oc-border bg-oc-background px-1.5 has-focus-visible:border-oc-ring',
          defaultClassNames.dropdown_root,
        ),
        dropdown: cn(
          'absolute inset-0 cursor-pointer opacity-0',
          defaultClassNames.dropdown,
        ),
        caption_label: cn(
          'text-sm font-medium text-oc-foreground select-none',
          captionLayout === 'label'
            ? ''
            : 'flex items-center gap-1 [&>svg]:size-3.5 [&>svg]:text-oc-muted-foreground',
          defaultClassNames.caption_label,
        ),
        month_grid: cn('w-full border-collapse', defaultClassNames.month_grid),
        weekdays: cn('flex', defaultClassNames.weekdays),
        weekday: cn(
          'size-8 text-xs font-medium text-oc-foreground select-none',
          defaultClassNames.weekday,
        ),
        week: cn('mt-2 flex w-full', defaultClassNames.week),
        week_number_header: cn('w-8 select-none', defaultClassNames.week_number_header),
        week_number: cn(
          'text-xs text-oc-muted-foreground select-none',
          defaultClassNames.week_number,
        ),
        day: cn(
          'group/day relative size-8 p-0 text-center select-none',
          defaultClassNames.day,
        ),
        range_start: cn(
          'relative after:absolute after:inset-y-0 after:left-1/2 after:right-0 after:bg-oc-primary/10 [&.rdp-range_start.rdp-range_end]:after:hidden',
          defaultClassNames.range_start,
        ),
        range_middle: cn('bg-oc-primary/10', defaultClassNames.range_middle),
        range_end: cn(
          'relative after:absolute after:inset-y-0 after:left-0 after:right-1/2 after:bg-oc-primary/10 [&.rdp-range_start.rdp-range_end]:after:hidden',
          defaultClassNames.range_end,
        ),
        today: cn('text-oc-foreground', defaultClassNames.today),
        outside: cn('text-oc-muted-foreground opacity-35', defaultClassNames.outside),
        disabled: cn('text-oc-foreground opacity-35', defaultClassNames.disabled),
        hidden: cn('invisible', defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => {
          return (
            <div data-slot="calendar" ref={rootRef} className={cn(className)} {...props} />
          )
        },
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === 'left') {
            return <LeftRegular className={cn('size-5', className)} {...props} />
          }

          if (orientation === 'right') {
            return <RightRegular className={cn('size-5', className)} {...props} />
          }

          return <DownRegular className={cn('size-4', className)} {...props} />
        },
        DayButton: ({ ...props }) => <CalendarDayButton locale={locale} {...props} />,
        ...(captionLayout === 'dropdown' ? { MonthCaption: CalendarMonthCaption } : {}),
        WeekNumber: ({ children, ...props }) => {
          return (
            <td {...props}>
              <div className="flex size-8 items-center justify-center text-center">{children}</div>
            </td>
          )
        },
        ...components,
      }}
      {...props}
    />
  )
}

const YEAR_PAGE_SIZE = 12

function startOfYearPage(year: number) {
  return Math.floor(year / YEAR_PAGE_SIZE) * YEAR_PAGE_SIZE
}

function monthShortNames(locale?: Partial<Locale>) {
  return Array.from({ length: 12 }, (_, month) =>
    new Date(2026, month, 1).toLocaleString(locale?.code ?? 'en-US', { month: 'short' }),
  )
}

function CalendarMonthCaption({
  calendarMonth,
  displayIndex,
  className,
  ...props
}: MonthCaptionProps) {
  const { goToMonth, dayPickerProps, formatters } = useDayPicker()
  const locale = dayPickerProps.locale as Partial<Locale> | undefined
  const startMonth = dayPickerProps.startMonth
  const endMonth = dayPickerProps.endMonth
  const [open, setOpen] = React.useState(false)
  const [view, setView] = React.useState<'months' | 'years'>('months')
  const [viewYear, setViewYear] = React.useState(calendarMonth.date.getFullYear())
  const rootRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (!open) {
      setView('months')
      setViewYear(calendarMonth.date.getFullYear())
    }
  }, [calendarMonth.date, open])

  React.useEffect(() => {
    if (!open) return

    function onPointerDown(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false)
      }
    }

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') setOpen(false)
    }

    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [open])

  const displayed = calendarMonth.date
  const yearPageStart = startOfYearPage(viewYear)
  const yearPageEnd = yearPageStart + YEAR_PAGE_SIZE - 1
  const minYear = startMonth?.getFullYear()
  const maxYear = endMonth?.getFullYear()

  function isMonthDisabled(month: number) {
    const first = new Date(viewYear, month, 1)
    const last = new Date(viewYear, month + 1, 0)
    if (startMonth && last < new Date(startMonth.getFullYear(), startMonth.getMonth(), 1)) {
      return true
    }
    if (endMonth && first > new Date(endMonth.getFullYear(), endMonth.getMonth(), 1)) {
      return true
    }
    return false
  }

  function isYearDisabled(year: number) {
    if (minYear !== undefined && year < minYear) return true
    if (maxYear !== undefined && year > maxYear) return true
    return false
  }

  const canPrevYear = minYear === undefined || viewYear - 1 >= minYear
  const canNextYear = maxYear === undefined || viewYear + 1 <= maxYear
  const canPrevYearPage = minYear === undefined || yearPageStart - 1 >= minYear
  const canNextYearPage = maxYear === undefined || yearPageEnd + 1 <= maxYear

  return (
    <div
      ref={rootRef}
      className={cn(
        'relative flex h-8 items-center [&_button]:cursor-pointer [&_button:disabled]:cursor-not-allowed',
        className,
      )}
      data-display-index={displayIndex}
      {...props}
    >
      <button
        type="button"
        className="rounded-md text-sm font-medium text-oc-foreground select-none hover:text-oc-primary"
        aria-expanded={open}
        aria-haspopup="dialog"
        onClick={() => setOpen((current) => !current)}
      >
        {formatters.formatCaption(displayed, { locale: locale as Locale | undefined })}
      </button>
      {open ? (
        <div
          role="dialog"
          aria-label="Select month and year"
          className="absolute top-[calc(100%+0.375rem)] left-0 z-50 w-56 rounded-lg border border-solid border-oc-border bg-oc-background p-2.5 shadow-oc-popup"
        >
          <div className="relative mb-1.5 h-0 w-full">
            <span className="absolute -top-3.5 left-6 size-2.5 rotate-45 border-t border-l border-solid border-oc-border bg-oc-background" />
          </div>
          <div className="mb-2 flex items-center justify-between gap-1">
            <button
              type="button"
              className="inline-flex size-7 items-center justify-center rounded-md text-oc-foreground disabled:opacity-35"
              disabled={view === 'months' ? !canPrevYear : !canPrevYearPage}
              aria-label={view === 'months' ? 'Previous year' : 'Previous years'}
              onClick={() =>
                setViewYear((year) =>
                  view === 'months' ? year - 1 : year - YEAR_PAGE_SIZE,
                )
              }
            >
              <LeftRegular className="size-4" />
            </button>
            {view === 'months' ? (
              <button
                type="button"
                className="rounded-md px-2 py-0.5 text-sm font-semibold text-oc-foreground hover:bg-oc-muted"
                onClick={() => setView('years')}
              >
                {viewYear}
              </button>
            ) : (
              <button
                type="button"
                className="rounded-md border border-solid border-oc-primary px-2 py-0.5 text-sm font-semibold text-oc-foreground"
                onClick={() => setView('months')}
              >
                {yearPageStart} - {yearPageEnd}
              </button>
            )}
            <button
              type="button"
              className="inline-flex size-7 items-center justify-center rounded-md text-oc-foreground disabled:opacity-35"
              disabled={view === 'months' ? !canNextYear : !canNextYearPage}
              aria-label={view === 'months' ? 'Next year' : 'Next years'}
              onClick={() =>
                setViewYear((year) =>
                  view === 'months' ? year + 1 : year + YEAR_PAGE_SIZE,
                )
              }
            >
              <RightRegular className="size-4" />
            </button>
          </div>
          {view === 'months' ? (
            <div className="grid grid-cols-3 gap-1">
              {monthShortNames(locale).map((label, month) => {
                const selected =
                  displayed.getFullYear() === viewYear && displayed.getMonth() === month
                const disabled = isMonthDisabled(month)
                return (
                  <button
                    key={label}
                    type="button"
                    disabled={disabled}
                    className={cn(
                      'h-8 rounded-md text-sm font-medium text-oc-foreground hover:bg-oc-primary/10 focus-visible:border focus-visible:border-solid focus-visible:border-oc-primary',
                      selected && 'bg-oc-primary/10',
                      disabled && 'text-oc-muted-foreground opacity-50',
                    )}
                    onClick={() => {
                      goToMonth(new Date(viewYear, month, 1))
                      setOpen(false)
                    }}
                  >
                    {label}
                  </button>
                )
              })}
            </div>
          ) : (
            <div className="grid grid-cols-3 gap-1">
              {Array.from({ length: YEAR_PAGE_SIZE }, (_, index) => yearPageStart + index).map(
                (year) => {
                  const selected = displayed.getFullYear() === year
                  const disabled = isYearDisabled(year)
                  return (
                    <button
                      key={year}
                      type="button"
                      disabled={disabled}
                      className={cn(
                        'h-8 rounded-md text-sm font-medium text-oc-foreground hover:bg-oc-primary/10 focus-visible:border focus-visible:border-solid focus-visible:border-oc-primary',
                        selected && 'bg-oc-primary/10',
                        disabled && 'text-oc-muted-foreground opacity-50',
                      )}
                      onClick={() => {
                        setViewYear(year)
                        setView('months')
                      }}
                    >
                      {year}
                    </button>
                  )
                },
              )}
            </div>
          )}
        </div>
      ) : null}
    </div>
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> }) {
  const defaultClassNames = getDefaultClassNames()
  const ref = React.useRef<HTMLButtonElement>(null)

  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <Button
      ref={ref}
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString(locale?.code)}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        'relative isolate z-10 size-8 min-w-8 rounded-full border-0 p-0 text-sm font-normal text-oc-foreground hover:bg-oc-primary/10',
